-- Generated by scripts/export_schema.py. The app creates these tables itself on first start.

CREATE TABLE audit_log (
	id SERIAL NOT NULL, 
	run_id INTEGER, 
	event VARCHAR(60) NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	detail TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_audit_log_run_id ON audit_log (run_id);

CREATE TABLE runs (
	id SERIAL NOT NULL, 
	parent_run_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	filename VARCHAR(300) NOT NULL, 
	file_size INTEGER NOT NULL, 
	doc_hash VARCHAR(64) NOT NULL, 
	page_count INTEGER, 
	extraction_method VARCHAR(40), 
	ocr_confidence FLOAT, 
	vendor_name VARCHAR(300), 
	vendor_id VARCHAR(20), 
	invoice_number VARCHAR(100), 
	invoice_number_norm VARCHAR(100), 
	invoice_date VARCHAR(20), 
	due_date VARCHAR(20), 
	po_number VARCHAR(30), 
	currency VARCHAR(3), 
	subtotal_minor BIGINT, 
	tax_minor BIGINT, 
	total_minor BIGINT, 
	decision VARCHAR(12) NOT NULL, 
	review_state VARCHAR(30) NOT NULL, 
	summary_line TEXT, 
	explanation TEXT, 
	duration_ms INTEGER, 
	fields_json TEXT, 
	checks_json TEXT, 
	stages_json TEXT, 
	po_json TEXT, 
	calc_json TEXT, 
	messages_json TEXT, 
	raw_text TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(parent_run_id) REFERENCES runs (id)
);

CREATE INDEX ix_runs_created_at ON runs (created_at);

CREATE INDEX ix_runs_decision ON runs (decision);

CREATE INDEX ix_runs_doc_hash ON runs (doc_hash);

CREATE INDEX ix_runs_invoice_number_norm ON runs (invoice_number_norm);

CREATE INDEX ix_runs_parent_run_id ON runs (parent_run_id);

CREATE INDEX ix_runs_po_number ON runs (po_number);

CREATE INDEX ix_runs_vendor_total ON runs (vendor_id, total_minor);

CREATE TABLE vendors (
	id VARCHAR(20) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	norm_name VARCHAR(200) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	country VARCHAR(5), 
	tax_id VARCHAR(50), 
	address VARCHAR(300), 
	PRIMARY KEY (id)
);

CREATE INDEX ix_vendors_norm_name ON vendors (norm_name);

CREATE TABLE approved_invoices (
	id SERIAL NOT NULL, 
	run_id INTEGER NOT NULL, 
	vendor_id VARCHAR(20) NOT NULL, 
	invoice_number_norm VARCHAR(100) NOT NULL, 
	doc_hash VARCHAR(64) NOT NULL, 
	total_minor BIGINT NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_approved_vendor_invoice UNIQUE (vendor_id, invoice_number_norm), 
	CONSTRAINT uq_approved_doc_hash UNIQUE (doc_hash), 
	UNIQUE (run_id), 
	FOREIGN KEY(run_id) REFERENCES runs (id)
);

CREATE TABLE documents (
	run_id INTEGER NOT NULL, 
	content BYTEA NOT NULL, 
	PRIMARY KEY (run_id), 
	FOREIGN KEY(run_id) REFERENCES runs (id)
);

CREATE TABLE purchase_orders (
	po_number VARCHAR(30) NOT NULL, 
	vendor_id VARCHAR(20) NOT NULL, 
	currency VARCHAR(3) NOT NULL, 
	amount_net BIGINT NOT NULL, 
	committed_net BIGINT NOT NULL, 
	tax_rate VARCHAR(10) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	description VARCHAR(300), 
	PRIMARY KEY (po_number), 
	FOREIGN KEY(vendor_id) REFERENCES vendors (id)
);

CREATE INDEX ix_purchase_orders_vendor_id ON purchase_orders (vendor_id);

CREATE TABLE review_actions (
	id SERIAL NOT NULL, 
	run_id INTEGER NOT NULL, 
	action VARCHAR(40) NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	note TEXT, 
	child_run_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(run_id) REFERENCES runs (id)
);

CREATE INDEX ix_review_actions_run_id ON review_actions (run_id);

CREATE TABLE po_lines (
	id SERIAL NOT NULL, 
	po_number VARCHAR(30) NOT NULL, 
	line_no INTEGER NOT NULL, 
	description VARCHAR(300) NOT NULL, 
	quantity VARCHAR(20) NOT NULL, 
	unit_price VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(po_number) REFERENCES purchase_orders (po_number)
);

CREATE INDEX ix_po_lines_po_number ON po_lines (po_number);
